(() => {
'use strict';
const $=s=>document.querySelector(s),vocab=window.VOCAB,canvas=$('#board'),ctx=canvas.getContext('2d');
const teams=[{name:'Đỏ',animal:'Mèo',emoji:'🐱',color:'#ce5666',fur:'#f8dfb3'},{name:'Xanh dương',animal:'Chó',emoji:'🐶',color:'#4c85c9',fur:'#d6b396'},{name:'Vàng',animal:'Gà',emoji:'🐔',color:'#ae811c',fur:'#fff1c9'},{name:'Xanh lá',animal:'Heo',emoji:'🐷',color:'#429b76',fur:'#efb5c2'}].map(t=>({...t,score:0,pos:0,point:[0,0]}));
const path=[];for(let x=0;x<4;x++)path.push([x*3,0]);for(let z=0;z<4;z++)path.push([12,z*3]);for(let x=4;x>0;x--)path.push([x*3,12]);for(let z=4;z>0;z--)path.push([0,z*3]);
let turn=0,round=1,phase='ready',choices=[],correctIndex=-1,lastRoll=0,hop=0,epoch=0,seen=new Set();
let width=0,height=0,unit=1,ox=0,oy=0;
const random=n=>{const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n};
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=random(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function project(x,z,y=0){return [ox+(x-z)*unit,oy+(x+z)*unit*.51-y*unit]}
function polygon(points,color,stroke){ctx.beginPath();points.forEach((p,i)=>{const q=project(...p);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.7;ctx.stroke()}}
function box(x,z,y,w,d,h,top,left,right){polygon([[x,z,y+h],[x+w,z,y+h],[x+w,z+d,y+h],[x,z+d,y+h]],top);polygon([[x,z+d,y],[x+w,z+d,y],[x+w,z+d,y+h],[x,z+d,y+h]],left);polygon([[x+w,z,y],[x+w,z+d,y],[x+w,z+d,y+h],[x+w,z,y+h]],right)}
function tree(x,z,s=1){box(x-.08,z-.08,.08,.16,.16,.6*s,'#b49a86','#b49a86','#987f6c');let y=.5;for(let i=0;i<2;i++){let r=(.5-i*.13)*s;polygon([[x-r,z-r,y],[x+r,z-r,y],[x,z,y+1*s]],'#9fc6ac');polygon([[x+r,z-r,y],[x+r,z+r,y],[x,z,y+1*s]],'#75ac91');polygon([[x+r,z+r,y],[x-r,z+r,y],[x,z,y+1*s]],'#87bba0');y+=.5*s}}
function house(x,z,s=1,color='#d8b7ca'){box(x,z,.06,s,s,s*.7,'#f7ebd7','#f6e6cf','#deceb9');polygon([[x-.1,z-.1,.7*s],[x+s+.1,z-.1,.7*s],[x+s/2,z-.1,1.25*s]],color);polygon([[x+s+.1,z-.1,.7*s],[x+s+.1,z+s+.1,.7*s],[x+s/2,z+s+.1,1.25*s],[x+s/2,z-.1,1.25*s]],'#ab88b4');polygon([[x-.1,z-.1,.7*s],[x+s/2,z-.1,1.25*s],[x+s/2,z+s+.1,1.25*s],[x-.1,z+s+.1,.7*s]],color);box(x+s*.36,z+s+.005,.06,s*.26,.01,s*.4,'#a88d84','#a88d84','#a88d84')}

function animal(t,i){const x=t.point[0]+.4+(i%2)*1.05,z=t.point[1]+.48+Math.floor(i/2)*1.05,y=.47+(i===turn?hop:0);box(x-.08,z-.08,y,.8,.8,.1,t.color,t.color,t.color);box(x+.05,z+.05,y+.1,.55,.5,.48,t.fur,t.fur,t.fur);box(x+.01,z+.01,y+.54,.62,.58,.43,t.fur,t.fur,t.fur);
if(i===0||i===3){polygon([[x+.02,z+.03,y+.97],[x+.2,z+.03,y+.97],[x+.02,z+.03,y+1.2]],i===0?'#eabca8':'#d98d9f');polygon([[x+.43,z+.03,y+.97],[x+.62,z+.03,y+.97],[x+.62,z+.03,y+1.2]],i===0?'#eabca8':'#d98d9f')}
if(i===1){box(x-.11,z+.1,y+.51,.2,.29,.45,'#9f7967','#9f7967','#8e6857');box(x+.57,z+.05,y+.51,.2,.27,.45,'#9f7967','#9f7967','#8e6857')}
if(i===2){box(x+.17,z+.13,y+.97,.22,.2,.22,'#dd727a','#dc6470','#c7505b');polygon([[x+.24,z+.61,y+.68],[x+.42,z+.61,y+.68],[x+.33,z+.88,y+.59]],'#e6b547')}
if(i===3)box(x+.15,z+.58,y+.59,.32,.13,.18,'#dd90a3','#dd90a3','#c67b8f');
const p=project(x+.31,z+.61,y+.8);ctx.fillStyle='#574455';ctx.beginPath();ctx.arc(p[0]-.12*unit,p[1]+.05*unit,.035*unit,0,Math.PI*2);ctx.arc(p[0]+.11*unit,p[1]-.07*unit,.035*unit,0,Math.PI*2);ctx.fill();if(i===turn){const q=project(x+.3,z+.3,y+1.65);ctx.fillStyle=t.color;ctx.font=`bold ${Math.max(13,unit*.39)}px Segoe UI`;ctx.textAlign='center';ctx.fillText('▼',q[0],q[1])}}
function container(x,z,y,c){box(x,z,y,1.4,.68,.55,c,c,'#789296');for(let k=.2;k<1.3;k+=.25)box(x+k,z+.69,y+.06,.03,.015,.42,'#ffffff55','#ffffff55','#ffffff55')}
function harbor(){box(3.15,3.15,.02,8.7,8.7,.06,'#a5dce0','#93ced5','#93ced5');for(let k=0;k<5;k++){polygon([[4+k*.8,8.7,.10],[4.6+k*.8,8.7,.10],[4.9+k*.8,8.85,.10],[4.3+k*.8,8.85,.10]],'#d0eeea')}
box(7.5,3.2,.1,4.3,3.7,.3,'#e5e0ce','#ccc8b8','#b6bbad');house(9.2,3.5,1.5,'#aebbd3');container(7.8,5.5,.45,'#b6a4d6');container(9.4,5.5,.45,'#e4b38d');container(9.4,5.5,1,'#8dbdba');
// Cargo ship with faceted bow and stacked containers.
polygon([[4.1,4.4,.1],[5.1,3.9,.1],[6.5,4.4,.1],[6.5,8,.1],[5.3,8.6,.1],[4.1,8,.1]],'#637f9f');box(4.2,4.5,.1,2.15,3.35,.45,'#f7e5d0','#8c9ab5','#7184a4');box(4.35,4.65,.56,.7,.75,.75,'#fff5e3','#e8dfcc','#d9d2c5');container(4.6,5.7,.56,'#d99ba3');container(4.6,6.5,.56,'#dabd74');container(4.6,6.5,1.11,'#98bcb9');
// Quayside crane and lifting hook.
box(8.15,7,.16,.45,.45,2.5,'#efcb83','#dec18a','#c9a66a');box(6.9,7,2.62,2.6,.3,.25,'#f3d995','#dfbb74','#d3ac63');box(7.1,7.09,1.5,.035,.035,1.14,'#7f8a98','#7f8a98','#7f8a98');box(7,7.04,1.4,.24,.12,.12,'#727d8c','#727d8c','#727d8c');
const q=project(8.1,10.3,.15);ctx.textAlign='center';ctx.fillStyle='#5c9099';ctx.font=`800 ${unit*.46}px Segoe UI`;ctx.fillText('GLOBAL TRADE PORT',q[0],q[1]);ctx.font=`600 ${unit*.28}px Segoe UI`;ctx.fillText('EXPORT  ↔  IMPORT',q[0],q[1]+unit*.45)}
function draw(){ctx.clearRect(0,0,width,height);const shadow=project(7.5,7.5,-.9);ctx.fillStyle='#738ba622';ctx.beginPath();ctx.ellipse(...shadow,unit*14.5,unit*7.4,0,0,Math.PI*2);ctx.fill();box(-.16,-.16,-.55,15.32,15.32,.55,'#dce4da','#b9c8c0','#a8bbb8');harbor();path.forEach(([x,z],i)=>{const c=['#e4b2ba','#b5cce7','#ead6a4','#b4d9c7'][Math.floor(i/4)];box(x+.05,z+.05,0,2.88,2.88,.3,c,'#b8b9c5','#a6acb7');box(x+.13,z+.13,.3,2.72,2.72,.04,'#faf7ee','#ebe5d9','#d4d6cc');box(x+.13,z+.13,.345,2.72,.34,.03,c,c,c);let q=project(x+1.5,z+.4,.38);ctx.textAlign='center';ctx.fillStyle='#625b75';ctx.font=`700 ${Math.max(10,unit*.33)}px Segoe UI`;ctx.fillText(String(i+1).padStart(2,'0'),...q);const term=vocab[i].term.replace(/\s*\([^)]*\)/g,'');const words=term.split(' '),lines=[];let line='';for(const word of words){if((line+' '+word).trim().length>18&&line){lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);q=project(x+1.48,z+1.6,.38);ctx.font=`600 ${Math.max(8,unit*.27)}px Segoe UI`;lines.slice(0,3).forEach((l,j)=>ctx.fillText(l,q[0],q[1]+j*Math.max(9,unit*.3)));if(i===teams[turn].pos){ctx.strokeStyle=teams[turn].color;ctx.lineWidth=2;ctx.beginPath();[[x,z,.36],[x+3,z,.36],[x+3,z+3,.36],[x,z+3,.36]].forEach((p,j)=>{const v=project(...p);j?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.closePath();ctx.stroke()}});teams.map((t,i)=>({t,i})).sort((a,b)=>a.t.point[0]+a.t.point[1]-b.t.point[0]-b.t.point[1]).forEach(({t,i})=>animal(t,i))}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;canvas.width=width*devicePixelRatio;canvas.height=height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);unit=Math.max(3,Math.min((width-40)/31,(height-240)/17));ox=width/2;oy=Math.max(185,(height-unit*15.3)/2+38);draw()}
new ResizeObserver(resize).observe(canvas);
function inspectTile(e){const r=canvas.getBoundingClientRect(),dx=(e.clientX-r.left-ox)/unit,dz=(e.clientY-r.top-oy+unit*.35)/(unit*.51),x=Math.floor((dx+dz)/6)*3,z=Math.floor((dz-dx)/6)*3,i=path.findIndex(p=>p[0]===x&&p[1]===z);$('.map-hint').textContent=i>=0?`Ô ${i+1} · ${vocab[i].term}`:'Rê chuột hoặc chạm vào ô để xem từ vựng.'}canvas.addEventListener('pointermove',inspectTile);canvas.addEventListener('pointerdown',inspectTile);
function update(){const t=teams[turn];document.documentElement.style.setProperty('--team',t.color);$('#team-name').textContent='Nhóm '+t.name;$('#team-avatar').textContent=t.emoji;$('#team-dot').style.background=t.color;$('#round').textContent=round;$('#scoreboard').innerHTML=teams.map((t,i)=>`<div class="team-score ${i===turn?'active':''}" style="--color:${t.color}"><div class="score-name">${t.emoji} ${t.name}</div><strong>${t.score}</strong><small>điểm</small><span class="turn-label">${i===turn?'Đang chơi':'Ô '+(t.pos+1)}</span></div>`).join('');$('#progress-label').textContent=`${seen.size} / 16`;$('#progress').style.width=`${seen.size/16*100}%`;draw()}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function roll(){if(phase!=='ready')return;phase='moving';const token=epoch,t=teams[turn];$('#roll').disabled=true;$('#phase').textContent='XÚC XẮC ĐANG LĂN';const dice=$('#dice');dice.classList.add('rolling');lastRoll=random(6)+1;for(let i=0;i<9;i++){dice.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][random(6)];await delay(60);if(epoch!==token)return}dice.classList.remove('rolling');dice.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][lastRoll-1];$('#phase').textContent=`NHÓM ${t.name.toUpperCase()} ĐI ${lastRoll} BƯỚC`;for(let i=0;i<lastRoll;i++){const old=path[t.pos];t.pos=(t.pos+1)%16;const dest=path[t.pos],start=performance.now();await new Promise(resolve=>{function frame(now){if(token!==epoch){resolve();return}const n=Math.min(1,(now-start)/230);t.point=[old[0]+(dest[0]-old[0])*n,old[1]+(dest[1]-old[1])*n];hop=Math.sin(n*Math.PI)*.75;draw();if(n<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)});if(token!==epoch)return}hop=0;question();update()}
function question(){phase='question';const t=teams[turn],item=vocab[t.pos];seen.add(t.pos);choices=shuffle([item.meaning,...shuffle([...new Set(vocab.filter(v=>v.meaning!==item.meaning).map(v=>v.meaning))]).slice(0,2)]);correctIndex=choices.indexOf(item.meaning);$('#phase').textContent='TỪ NÀY CÓ NGHĨA LÀ GÌ?';$('#tile-tag').textContent=`Ô ${t.pos+1} · Lắc ${lastRoll}`;$('#content').replaceChildren();const icon=document.createElement('div');icon.className='question-emoji';icon.textContent=t.emoji;const h=document.createElement('h2');h.textContent=item.term;const p=document.createElement('p');p.textContent=`Nhóm ${t.name}, chọn nghĩa tiếng Việt chính xác`;$('#content').append(icon,h,p);$('#roll').classList.add('hidden');$('#answers').replaceChildren();choices.forEach((s,i)=>{const b=document.createElement('button');b.className='answer';const n=document.createElement('b');n.textContent=String(i+1);const text=document.createElement('span');text.textContent=s;b.append(n,text);b.onclick=()=>answer(i);$('#answers').append(b)});$('#answers button').focus();$('#keyhint').textContent='Chọn đáp án bằng phím 1, 2 hoặc 3'}
function answer(i){if(phase!=='question'||!Number.isInteger(i)||i<0||i>2)return;phase='result';const t=teams[turn],item=vocab[t.pos],correct=i===correctIndex;if(correct)t.score+=10;[...$('#answers').children].forEach((b,j)=>{b.disabled=true;if(j===correctIndex)b.classList.add('correct');else if(j===i)b.classList.add('wrong')});const p=document.createElement('p');p.className='result';p.textContent=correct?`Chính xác! Nhóm ${t.name} +10 điểm.`:`Chưa đúng. +0 điểm. Đáp án: ${item.meaning}`;const def=document.createElement('p');def.className='definition';def.textContent=item.definition;$('#content').append(p,def);$('#phase').textContent=correct?'GHI ĐIỂM CHO NHÓM!':'GHI NHỚ CHO LẦN SAU';$('#next').textContent=`Đến lượt nhóm ${teams[(turn+1)%4].name} →`;$('#next').classList.remove('hidden');$('#keyhint').textContent='Nhấn Enter để chuyển nhóm';update();$('#next').focus()}
function ready(){phase='ready';const t=teams[turn];$('#content').innerHTML=`<div class="dice" id="dice">⚄</div><h2>Nhóm ${t.name} sẵn sàng?</h2><p>Lắc xúc xắc, chọn đúng nghĩa và ghi 10 điểm cho nhóm.</p>`;$('#answers').replaceChildren();$('#roll').classList.remove('hidden');$('#roll').disabled=false;$('#next').classList.add('hidden');$('#phase').textContent='ĐẾN LƯỢT NHÓM '+t.name.toUpperCase();$('#tile-tag').textContent='Ô '+(t.pos+1);$('#keyhint').textContent='Nhấn Space để lắc · 1–3 để chọn';update()}
function next(){if(phase!=='result')return;turn=(turn+1)%4;if(turn===0)round++;ready();$('#roll').focus()}
$('#roll').onclick=roll;$('#next').onclick=next;$('#reset').onclick=()=>{if(!confirm('Chơi lại từ đầu? Điểm và vị trí của cả 4 nhóm sẽ được đặt lại.'))return;epoch++;teams.forEach(t=>{t.score=0;t.pos=0;t.point=[0,0]});turn=0;round=1;hop=0;seen.clear();ready()};$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=$('#start').onclick=()=>$('#help-dialog').close();document.addEventListener('keydown',e=>{if($('#help-dialog').open||e.repeat)return;if(e.code==='Space'&&phase==='ready'){e.preventDefault();roll()}else if(['1','2','3'].includes(e.key)&&phase==='question'){e.preventDefault();answer(Number(e.key)-1)}else if(e.key==='Enter'&&phase==='result'&&e.target!==$('#next')){e.preventDefault();next()}});
const getState=()=>({phase,activeTeam:teams[turn].name,round,lastRoll,teams:teams.map(t=>({name:t.name,score:t.score,tile:t.pos+1})),term:phase==='question'?vocab[teams[turn].pos].term:null,options:phase==='question'?[...choices]:[],wordCount:vocab.length});
window.vocabGame={getState,roll,answer,next};
if(document.modelContext?.registerTool){const result=()=>({content:[{type:'text',text:JSON.stringify(getState())}]});const registrations=[{name:'roll_dice',description:'Roll and move the current team 1–6 tiles.',inputSchema:{type:'object',properties:{}},execute:async()=>{if(phase!=='ready')throw new Error('Complete the current turn first');await roll();return result()}},{name:'answer_vocabulary',description:'Choose option 1–3 and award the current team 10 points if correct.',inputSchema:{type:'object',properties:{option:{type:'integer',minimum:1,maximum:3}},required:['option']},execute:async({option})=>{if(phase!=='question'||!Number.isInteger(option)||option<1||option>3)throw new Error('Choose option 1–3 during a question');answer(option-1);return result()}},{name:'next_team',description:'Finish the answered question and switch to the next team.',inputSchema:{type:'object',properties:{}},execute:async()=>{if(phase!=='result')throw new Error('Answer first');next();return result()}}];for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool({...tool,annotations:{readOnlyHint:false}})).catch(()=>{})}catch{}}}
ready();resize();
})();
